with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'أرصاد التضاريس والبيئات الجبلية المتقدمة','الجريان والموجات الجبلية والرياح المحلية والهطول التضاريسي والثلوج والرصد والنمذجة فوق التضاريس المعقدة.',57,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الجريان والرياح الجبلية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الهطول والثلوج والرصد الجبلي',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('orographic-flow-regimes','أنظمة الجريان فوق التضاريس','الجريان المستقر وغير المستقر فوق الجبال','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتغير الجريان فوق التضاريس بين أنظمة مستقرة وغير مستقرة بحسب عدد فرويد والاستقرار والسرعة وشكل الجبل. قد يحدث عبور للهواء فوق القمة أو انحراف حول العائق أو تشكل موجات جبلية."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل أنظمة الجريان فوق التضاريس على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج أنظمة الجريان فوق التضاريس على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن جرياناً فوق جبل في طبقة مستقرة وآخر في طبقة ضعيفة الاستقرار."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح أنظمة الجريان فوق التضاريس أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7560,50,'["شرح آليات أنظمة الجريان فوق التضاريس","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الجريان والرياح الجبلية'),
('mountain-wave-generation','تولد الموجات الجبلية','الإزاحة الرأسية والطفو والاستقرار','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تنشأ الموجات الجبلية عندما يجبر الجريان المستقر على الصعود والهبوط فوق التضاريس، فتنتشر اضطرابات الجاذبية رأسياً وأفقياً. تعتمد خصائصها على الاستقرار والرياح وشكل التضاريس."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل تولد الموجات الجبلية على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج تولد الموجات الجبلية على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد الظروف التي تسمح بانتشار موجة جبلية رأسياً بدلاً من اضمحلالها."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح تولد الموجات الجبلية أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7570,50,'["شرح آليات تولد الموجات الجبلية","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الجريان والرياح الجبلية'),
('mountain-wave-breaking-turbulence','انكسار الموجات الجبلية والاضطراب','تشبع الموجة وفقدان الاستقرار','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد تتضخم الموجات الجبلية وتنكسر عندما تصبح سعتها كبيرة أو يتغير الاستقرار والقص، فتنتج مناطق اضطراب قوية في المستويات العليا أو قرب القمم. يصعب تحديدها من الرصد السطحي وحده."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل انكسار الموجات الجبلية والاضطراب على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج انكسار الموجات الجبلية والاضطراب على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف يمكن لموجة جبلية أن تنتج اضطراباً بعيداً عن القمة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح انكسار الموجات الجبلية والاضطراب أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7580,50,'["شرح آليات انكسار الموجات الجبلية والاضطراب","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الجريان والرياح الجبلية'),
('foehn-and-chinook-winds','رياح الفوهن والشنوك','التسخين والهبوط على السفوح المعاكسة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تظهر رياح الفوهن والشنوك دافئة وجافة نسبياً على السفوح المعاكسة للرياح، نتيجة مزيج من التكاثف وفقد الرطوبة والهبوط الانضغاطي. تختلف آلياتها بحسب الاستقرار وارتفاع التكاثف وشكل الجبل."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل رياح الفوهن والشنوك على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج رياح الفوهن والشنوك على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن تفسيراً حرارياً مبسطاً لرياح الفوهن مع دور الموجات الجبلية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح رياح الفوهن والشنوك أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7590,50,'["شرح آليات رياح الفوهن والشنوك","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الجريان والرياح الجبلية'),
('downslope-windstorms','عواصف الرياح الهابطة','تسارع الجريان وتراكيب الموجات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد تنتج رياح هابطة شديدة على السفوح المعاكسة عند وجود جريان قوي وطبقية مناسبة وموجات جبلية منظمة. يتطلب التشخيص فحص الرياح الرأسية والأفقية والاستقرار والضغط على جانبي الجبل."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل عواصف الرياح الهابطة على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج عواصف الرياح الهابطة على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد الحقول التي تساعد على تشخيص احتمال رياح هابطة شديدة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح عواصف الرياح الهابطة أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7600,50,'["شرح آليات عواصف الرياح الهابطة","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الجريان والرياح الجبلية'),
('gap-winds-mountain-passes','رياح الممرات الجبلية','تسارع الهواء عبر الفجوات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتسارع الرياح عبر الممرات والفجوات عندما يوجه فرق الضغط الجريان خلال تضييق التضاريس. تعتمد السرعة على هندسة الممر والاستقرار والاحتكاك واتجاه الرياح الخلفية."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل رياح الممرات الجبلية على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج رياح الممرات الجبلية على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر لماذا قد تكون الرياح في ممر جبلي أقوى من المناطق المحيطة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح رياح الممرات الجبلية أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7610,50,'["شرح آليات رياح الممرات الجبلية","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الجريان والرياح الجبلية'),
('valley-breeze-mountain-breeze','نسيم الوادي ونسيم الجبل','الدوران الحراري اليومي المحلي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ نسيم الوادي نهاراً غالباً مع تسخين السفوح وصعود الهواء، بينما يظهر نسيم الجبل ليلاً مع تبريد السفوح وهبوط الهواء نحو الوادي. تتداخل هذه الدورة مع الرياح الخلفية والسحب."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل نسيم الوادي ونسيم الجبل على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج نسيم الوادي ونسيم الجبل على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ارسم دورة يومية مبسطة لنسيم الوادي والجبل وحدد عوامل تعديلها."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح نسيم الوادي ونسيم الجبل أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7620,50,'["شرح آليات نسيم الوادي ونسيم الجبل","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الجريان والرياح الجبلية'),
('cold-air-pooling-valleys','تجمع الهواء البارد في الأودية','الانقلابات الحرارية والتهوية الضعيفة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتجمع الهواء البارد في قيعان الأودية والأحواض خلال الليالي الهادئة بسبب التصريف الكثافي وضعف الخلط، ما يعزز الانقلاب الحراري والضباب والصقيع. يتأثر ذلك بشكل الوادي والغطاء السحابي والرياح."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل تجمع الهواء البارد في الأودية على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج تجمع الهواء البارد في الأودية على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل مقطعاً حرارياً عبر وادٍ لتحديد موضع تجمع الهواء البارد."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح تجمع الهواء البارد في الأودية أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7630,50,'["شرح آليات تجمع الهواء البارد في الأودية","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الجريان والرياح الجبلية'),
