40,50,'["شرح آليات الطبقة الحدية فوق التضاريس","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الجريان والرياح الجبلية'),
('orographic-precipitation-processes','آليات الهطول التضاريسي','الرفع والتكاثف والتغذية السحابية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يعزز الرفع التضاريسي صعود الهواء الرطب وتكاثفه على السفوح المواجهة للرياح، لكن مقدار الهطول يعتمد على الاستقرار والرياح الدقيقة وعمق السحب والعمليات المجهرية."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل آليات الهطول التضاريسي على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج آليات الهطول التضاريسي على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر لماذا لا يتساوى الهطول دائماً بين السفح المواجه والسفح المعاكس."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح آليات الهطول التضاريسي أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7650,50,'["شرح آليات آليات الهطول التضاريسي","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الجريان والرياح الجبلية'),
('rain-shadow-climatology','مناخ ظل المطر','الجفاف النسبي خلف الحواجز الجبلية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ ظل المطر عندما تفقد الكتل الهوائية جزءاً من رطوبتها أثناء صعودها فوق الجبال، ثم تهبط وتسخن على الجانب المعاكس. تتأثر شدة الظل بارتفاع السلسلة واتجاه الرياح والموسم ومصادر الرطوبة."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل مناخ ظل المطر على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج مناخ ظل المطر على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن مناخ منطقتين على جانبي سلسلة جبلية باستخدام اتجاهات الرياح والهطول."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح مناخ ظل المطر أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7660,50,'["شرح آليات مناخ ظل المطر","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الهطول والثلوج والرصد الجبلي'),
('orographic-clouds-lenticular','السحب العدسية والسحب التضاريسية','الموجات المستقرة والتكاثف الموضعي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتشكل السحب العدسية في مناطق صعود موجي مستقر فوق التضاريس، وقد تبقى شبه ثابتة مكانياً رغم استمرار مرور الهواء خلالها. لا تعني هيئة السحابة وحدها أن كل المنطقة المحيطة مضطربة."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل السحب العدسية والسحب التضاريسية على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج السحب العدسية والسحب التضاريسية على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر ثبات موقع سحابة عدسية رغم سرعة الرياح في طبقة الجو."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح السحب العدسية والسحب التضاريسية أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7670,50,'["شرح آليات السحب العدسية والسحب التضاريسية","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الهطول والثلوج والرصد الجبلي'),
('rotor-clouds-mountain-turbulence','سحب الدوامة والاضطراب أسفل الموجات','الدوامات تحت الموجية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد تتكون دوامات أفقية قوية أسفل الموجات الجبلية وتظهر أحياناً كسحب دوامية، وترتبط باضطراب شديد قرب السفوح المعاكسة. تمثل خطراً جوياً للطيران وتتطلب تحليلاً رأسياً دقيقاً."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل سحب الدوامة والاضطراب أسفل الموجات على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج سحب الدوامة والاضطراب أسفل الموجات على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد العلاقة بين الموجة الجبلية ومنطقة الدوامة أسفلها في مقطع رأسي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح سحب الدوامة والاضطراب أسفل الموجات أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7680,50,'["شرح آليات سحب الدوامة والاضطراب أسفل الموجات","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الهطول والثلوج والرصد الجبلي'),
('mountain-precipitation-phase','طور الهطول في البيئات الجبلية','الثلج والمطر المتجمد والمطر','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتغير طور الهطول مع الملف الحراري الرأسي ودرجة حرارة البصيلة الرطبة وعمق الطبقات الدافئة والباردة. تؤدي فروق الارتفاع الصغيرة أحياناً إلى اختلاف كبير في نوع الهطول على المنحدرات."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل طور الهطول في البيئات الجبلية على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج طور الهطول في البيئات الجبلية على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل ملفاً حرارياً رأسياً لتحديد احتمال الثلج أو المطر المتجمد أو المطر."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح طور الهطول في البيئات الجبلية أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7690,50,'["شرح آليات طور الهطول في البيئات الجبلية","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الهطول والثلوج والرصد الجبلي'),
('snowpack-energy-balance','ميزانية الطاقة للغطاء الثلجي','الإشعاع والتدفقات والذوبان','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتحدد طاقة الغطاء الثلجي من صافي الإشعاع والتدفقات المحسوسة والكامنة وحرارة المطر وانتقال الحرارة داخل الثلج. تؤثر خصائص البياض والحجم الحبيبي والرطوبة في سرعة الذوبان."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل ميزانية الطاقة للغطاء الثلجي على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج ميزانية الطاقة للغطاء الثلجي على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"أنشئ ميزانية طاقة نوعية لغطاء ثلجي خلال يوم مشمس."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح ميزانية الطاقة للغطاء الثلجي أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7700,50,'["شرح آليات ميزانية الطاقة للغطاء الثلجي","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الهطول والثلوج والرصد الجبلي'),
('mountain-snow-water-equivalent','المكافئ المائي للغطاء الثلجي','مخزون المياه في الثلوج','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل المكافئ المائي للثلج عمق الماء الناتج عن ذوبان الغطاء الثلجي، وهو مؤشر أساسي لتقدير موارد المياه ومخاطر السيول الربيعية. يتطلب قياسه معرفة الكثافة والعمق والتوزيع المكاني."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل المكافئ المائي للغطاء الثلجي على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج المكافئ المائي للغطاء الثلجي على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح الفرق بين عمق الثلج والمكافئ المائي مع مثال عددي مبسط."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح المكافئ المائي للغطاء الثلجي أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7710,50,'["شرح آليات المكافئ المائي للغطاء الثلجي","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الهطول والثلوج والرصد الجبلي'),
('avalanche-weather-conditions','الظروف الجوية المؤثرة في الانهيارات الثلجية','تراكم الثلج والرياح والحرارة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تؤثر كثافة الهطول الثلجي والرياح وإعادة توزيع الثلج والحرارة في استقرار الغطاء الثلجي. يعتمد تقييم الخطر على دمج الرصد الميداني وخصائص طبقات الثلج والطقس، ولا يمكن استنتاجه من كمية الثلج وحدها."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل الظروف الجوية المؤثرة في الانهيارات الثلجية على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج الظروف الجوية المؤثرة في الانهيارات الثلجية على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صنف العوامل الجوية التي قد تزيد عدم استقرار طبقات الثلج، دون محاولة تقدير مسار ميداني."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح الظروف الجوية المؤثرة في الانهيارات الثلجية أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7720,50,'["شرح آليات الظروف الجوية المؤثرة في الانهيارات الثلجية","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الهطول والثلوج والرصد الجبلي'),
('mountain-glacier-meteorology','أرصاد الأنهار الجليدية','ميزانية الكتلة والتبادل السطحي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتأثر الأنهار الجليدية بالإشعاع والحرارة والرطوبة والرياح والهطول وتراكم الثلج، وتستخدم ميزانية الكتلة لتقدير التغير طويل الأمد. يختلف التوازن بين مناطق التراكم والانصهار."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل أرصاد الأنهار الجليدية على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج أرصاد الأنهار الجليدية على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد متغيرات محطة أرصاد مناسبة لمراقبة ميزانية كتلة نهر جليدي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح أرصاد الأنهار الجليدية أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7730,50,'["شرح آليات أرصاد الأنهار الجليدية","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الهطول والثلوج والرصد الجبلي'),
('high-altitude-weather-station-design','تصميم محطات الأرصاد عالية الارتفاع','التعرض والثلج والطاقة والاتصال','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تواجه محطات القمم تحديات الرياح الشديدة والجليد وتراكم الثلج ونقص الطاقة والاتصال. يتطلب التصميم اختيار موقع ممثل وتثبيتاً مناسباً وخطة صيانة ومعايرة تتناسب مع البيئة."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل تصميم محطات الأرصاد عالية الارتفاع على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج تصميم محطات الأرصاد عالية الارتفاع على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ضع مواصفات تشغيلية لمحطة آلية على قمة جبلية مع بيان قيود القياس."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح تصميم محطات الأرصاد عالية الارتفاع أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7740,50,'["شرح آليات تصميم محطات الأرصاد عالية الارتفاع","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الهطول والثلوج والرصد الجبلي'),
('complex-terrain-nwp-verification','التحقق من النماذج العددية فوق التضاريس المعقدة','التمثيل الشبكي والارتفاع ومطابقة المحطات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتأثر تقييم النماذج فوق التضاريس باختلاف ارتفاع الشبكة عن ارتفاع المحطة وبتمثيل الوديان والقمم والعمليات المحلية. يجب فصل خطأ النموذج عن خطأ التمثيل المكاني وعدم الاكتفاء بمتوسط إقليمي."},{"type":"heading","text":"المتغيرات المؤثرة"},{"type":"text","text":"يعتمد تحليل التحقق من النماذج العددية فوق التضاريس المعقدة على شكل التضاريس وارتفاعها واتجاهها، والاستقرار الرأسي والرياح والرطوبة والحرارة والإشعاع وخصائص السطح. تختلف الاستجابة مكانياً خلال مسافات قصيرة، لذا ينبغي استخدام بيانات عالية الدقة والتحقق من تمثيل المحطة أو الشبكة."},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد اتجاه الجريان بالنسبة إلى التضاريس ومقاطع الارتفاع.","افحص الاستقرار والقص والرياح عبر طبقات رأسية.","اربط القياسات السطحية بالمقاطع الرأسية وصور السحب.","قارن السفوح والقمم والأودية مع مراعاة اختلاف الارتفاع.","وثق حدود الدقة المكانية وتأثير موقع أجهزة الرصد."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حالة جوية جبلية","text":"اختر منطقة جبلية وطبّق منهج التحقق من النماذج العددية فوق التضاريس المعقدة على بيانات محطة ومقطع نموذج عددي وصورة فضائية. اشرح التباين بين المواقع ولا تفترض أن قياس نقطة واحدة يمثل كامل التضاريس."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم طريقة لمقارنة توقعات نموذج جبلي بمحطات مختلفة الارتفاع مع تصحيح أثر التمثيل."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["إهمال أثر الارتفاع واتجاه السفح.","استخدام شبكة عددية أخشن من مقياس الظاهرة.","الخلط بين الرياح الخلفية والدوران المحلي.","تفسير السحب التضاريسية دون بيانات رأسية.","تعميم قياس محطة في وادٍ على قمة جبلية."]},{"type":"callout","text":"في التضاريس المعقدة، التمثيل المكاني والارتفاع واتجاه السفح عناصر أساسية في تفسير كل قياس وتوقع."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح التحقق من النماذج العددية فوق التضاريس المعقدة أن التضاريس تعيد تشكيل الجريان والطبقة الحدية والهطول والثلوج، وتفرض متطلبات خاصة للرصد والنمذجة والتحقق."}]}'::jsonb,7750,50,'["شرح آليات التحقق من النماذج العددية فوق التضاريس المعقدة","تحليل تأثير التضاريس في الحقول الجوية","تقييم الرصد والنمذجة في البيئات الجبلية"]'::jsonb,'الهطول والثلوج والرصد الجبلي')
)
insert into public.academy_lessons(course_id,chapter_id,unit_id,chapter_title,unit_title,slug,title,summary,content,published,sort_order,estimated_minutes,learning_objectives,level)
select c.id,ch.id,case when d.unit_title='الجريان والرياح الجبلية' then u1.id else u2.id end,'أرصاد التضاريس والبيئات الجبلية المتقدمة',d.unit_title,d.slug,d.title,d.summary,d.content,false,d.ord,d.mins,d.objectives,'advanced'
from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,level=excluded.level;